ALTER POLICY "Public read free-resources" ON storage.objects USING (bucket_id = 'free-resources' AND (public.has_role(auth.uid(), 'admin') OR EXISTS (SELECT 1 FROM public.free_resources r WHERE r.is_active = true AND r.file_path = objects.name)));
ALTER POLICY "Public can read free-resources objects" ON storage.objects USING (bucket_id = 'free-resources' AND (public.has_role(auth.uid(), 'admin') OR EXISTS (SELECT 1 FROM public.free_resources r WHERE r.is_active = true AND r.file_path = objects.name)));
ALTER POLICY "Testimonial images are publicly readable" ON storage.objects USING (bucket_id = 'testimonial-images' AND (public.has_role(auth.uid(), 'admin') OR EXISTS (SELECT 1 FROM public.testimonials t WHERE t.image_url = objects.name AND t.is_public = true AND t.status IN ('approved','published'))));